var o={en:`A refactor publishes directly before commit and removes the consumer dead-letter route. Events may describe orders that were never committed or disappear downstream.`,ua:`Рефакторинг публікує напряму до commit і прибирає dead-letter споживача. Події можуть описувати незбережені замовлення або зникати на шляху.`};var t={en:[`Remove command→broker shortcut.`,`Restore publisher→store and consumer→dlq.`,`Explain the crash window, bounded retry and replay verification.`],ua:[`Прибери command→broker.`,`Віднови publisher→store і consumer→dlq.`,`Поясни вікно аварії, обмежені повтори та перевірку відтворення.`]};var a=[{en:`There is no non-atomic command-to-broker path.`,ua:`Немає неатомарної публікації з команди в брокер.`},{en:`Outbox publication and dead-letter recovery routes exist.`,ua:`Є шляхи outbox і dead-letter відновлення.`}];var n={remove:[`publisher->store`,`consumer->dlq`],add:[{from:`command`,to:`broker`,kind:`event`,label:`Intentional defect / Навмисна помилка`}]};var d={scenario:o,tasks:t,checks:a,mutations:n};export{a as checks,d as default,n as mutations,o as scenario,t as tasks};